from pathlib import Path
import difflib, hashlib, json, os, shutil, subprocess
root=Path('artifacts/git_project_transaction'); root.mkdir(parents=True,exist_ok=True)
base={'branch':'git_project','field':'repository_state','value':'uninitialized','branch_name':'main','bbzps_ignored':False,'large_artifacts_ignored':False,'dist_preserved_local':True,'secret_files_staged':0}
