(root/'ROLLBACK.sh').write_text('#!/usr/bin/env bash\nset -euo pipefail\nTARGET="$1"\nBASELINE="$2"\ncp -- "$BASELINE" "$TARGET"\nprintf \'ROLLBACK_RESTORED=%s\\n\' "$TARGET"\n',encoding='utf-8'); os.chmod(root/'ROLLBACK.sh',0o755)
