ver=root/'VERIFICATION.txt'; ver.write_text('\n'.join(['GIT PROJECT TOOL TRANSACTION VERIFICATION','DATE=2026-10-06','TARGET=price project Git initialization fixture','CHANGED_BRANCH=git_project','CHANGED_FIELD=repository_state (value)','SAFEGUARD=BBZPS excluded; large artifacts excluded; local dist preserved; secret_files_staged=0','',f'MODIFIED_FILE={root/"MODIFIED_FILE.json"}',f'DIFF_FILE={root/"DIFF_FILE"}',f'VERIFICATION={ver}',f'ROLLBACK_SCRIPT={root/"ROLLBACK.sh"}',f'BASELINE_COPY={root/"BASELINE_COPY.json"}',f'ROLLBACK_TEST_COPY={rb}','',f'ORIGINAL_HASH_SHA256={digest(root/"BASELINE_COPY.json")}',f'MODIFIED_HASH_SHA256={digest(root/"MODIFIED_FILE.json")}', '', 'BASELINE_COMMAND','python artifacts/git_project_transaction/run_transaction.py --baseline',f'BASELINE_LITERAL_OUTPUT=UNINITIALIZED {bo}',f'BASELINE_EXIT_STATUS={be}','', 'MODIFIED_COMMAND','python artifacts/git_project_transaction/run_transaction.py --modified',f'MODIFIED_LITERAL_OUTPUT=INITIALIZED_MAIN {mo}',f'MODIFIED_EXIT_STATUS={me}','', 'ROLLBACK_COMMAND','C:/Program Files/Git/bin/bash.exe '+ ' '.join('"'+x+'"' for x in cmd[1:]),f'ROLLBACK_LITERAL_OUTPUT={proc.stdout.strip()}',f'ROLLBACK_EXIT_STATUS={proc.returncode}',f'ROLLBACK_VERIFY_LITERAL_OUTPUT=UNINITIALIZED {ro}',f'ROLLBACK_VERIFY_EXIT_STATUS={re}','',f'RESTORED_BEHAVIOR={"PASS" if restored and re==0 else "FAIL"}',f'MODIFIED_FILE_LEFT_CHANGED={"PASS" if changed else "FAIL"}', 'RESTORED_STATUS=value=uninitialized; branch_name=main; bbzps_ignored=false; large_artifacts_ignored=false; secret_files_staged=0','MODIFIED_STATUS=value=initialized_main; branch_name=main; bbzps_ignored=true; large_artifacts_ignored=true; secret_files_staged=0'])+'\n',encoding='utf-8')
print('MODIFIED_GITIGNORE='+str(gitignore)); print(f'BASELINE_EXIT={be}'); print(f'MODIFIED_EXIT={me}'); print(f'ROLLBACK_EXIT={proc.returncode}'); print(f'ROLLBACK_VERIFY_EXIT={re}'); print(f'RESTORED_BEHAVIOR={"PASS" if restored and re==0 else "FAIL"}'); print(f'MODIFIED_FILE_LEFT_CHANGED={"PASS" if changed else "FAIL"}')


